// Normalize inbound lead from the assessment funnel or correspondence form.
// Expected body: { name, email, source?, goal?, message? }
const b = $input.first().json.body ?? $input.first().json;
const allowedSources = ['Website Assessment', 'Correspondence Form', 'Instagram', 'TikTok', 'Threads', 'Referral', 'Other'];
const source = allowedSources.includes(b.source) ? b.source : 'Website Assessment';
if (!b.email) { throw new Error('Lead payload missing email'); }
return [{ json: {
  name: b.name || b.email.split('@')[0],
  email: String(b.email).trim().toLowerCase(),
  source,
  goal: b.goal || b.message || '',
  isAssessment: source === 'Website Assessment'
} }];
